/*=============== ZERO-FAIL EMBEDDED IMAGE FALLBACK ===============*/
(function () {
  const BASE64_FALLBACKS = {
    "santa.png": "data:image/png;base64,",
    "bell.png": "data:image/png;base64,",
    "star.png": "data:image/png;base64,"
  };

  const CDN_FALLBACKS = {
    "santa.png": "https://cdn.jsdelivr.net/gh/bedimcode/responsive-christmas-website-3@main/assets/img/santa.png",
    "bell.png": "https://cdn.jsdelivr.net/gh/bedimcode/responsive-christmas-website-3@main/assets/img/bell.png",
    "star.png": "https://cdn.jsdelivr.net/gh/bedimcode/responsive-christmas-website-3@main/assets/img/star.png",
    "snowman.jpg": "assets/img/snowman.jpg"
  };

  function getFileName(src) {
    if (!src) return "";
    const match = src.match(/([^/?#]+)\.(png|jpg|jpeg|svg|webp)/i);
    return match ? match[0].toLowerCase() : "";
  }

  function handleImgError(img) {
    if (!img || img.dataset.fbHandled === "done") return;
    const src = img.getAttribute("src") || "";
    const filename = getFileName(src);
    if (!filename) return;

    const b64 = BASE64_FALLBACKS[filename];
    if (b64) {
      img.dataset.fbHandled = "done";
      img.src = b64;
      return;
    }

    const cdn = CDN_FALLBACKS[filename];
    if (cdn && img.src !== cdn) {
      img.dataset.fbHandled = "cdn";
      img.src = cdn;
    }
  }

  window.handleImgError = handleImgError;

  // Intercept any load failure globally
  window.addEventListener("error", function (e) {
    if (e.target && e.target.tagName === "IMG") {
      handleImgError(e.target);
    }
  }, true);

  // Scan on DOM ready and window load to fix any images that already failed
  function scanAndRecover() {
    const images = document.querySelectorAll("img");
    images.forEach(function (img) {
      if (img.complete && (img.naturalWidth === 0 || img.naturalHeight === 0)) {
        handleImgError(img);
      }
    });
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", scanAndRecover);
  } else {
    scanAndRecover();
  }
  window.addEventListener("load", scanAndRecover);
})();
